const input = $json;
const projectSlug = String(input['Project slug'] ?? '').trim();
if (!projectSlug) throw new Error('Enter your Blogizi project slug.');
const title = String(input.Title ?? '').trim();
const content = String(input['Article Markdown'] ?? '').trim();
const description = String(input['Meta description'] ?? '').trim();
const keyword = String(input['SEO keyword'] ?? '').trim();
const customSlug = String(input.Slug ?? '').trim();
if (!title) throw new Error('Enter an article title.');
if (!content) throw new Error('Enter the article body as Markdown.');
const slug = customSlug || title
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
if (!slug || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
  throw new Error('Enter a Slug using lowercase letters, numbers, and hyphens, e.g. my-first-post.');
}
return { json: { projectSlug, title, slug, description, keyword, content } };
